public class ClimbStairs {
    public int climbStairs(int n) {
        // base case: n=1 → 1, n=2 → 2
        if (n <= 2) return n;

        int prev2 = 1; // dp[i-2], 初始 = dp[1]
        int prev1 = 2; // dp[i-1], 初始 = dp[2]

        for (int i = 3; i <= n; i++) {
            int cur = prev1 + prev2; // dp[i] = dp[i-1] + dp[i-2]
            prev2 = prev1;           // 滚动：旧的 prev1 变成新的 prev2
            prev1 = cur;             // 滚动：cur 变成新的 prev1
        }

        return prev1; // 循环结束，prev1 == dp[n]
    }
}
